use super::plugin_schema_defs::schema_from_state;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::prelude::ValueAsMutContainer;
use simd_json::{json, OwnedValue as Value};
use std::net::TcpStream;
use std::time::Duration;

const DEFAULT_QDRANT_ENDPOINT: &str = "http://127.0.0.1:6334";
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct KnowledgeState {
    pub status: String,
    pub stores: Value,
    pub embedding: Value,
    pub config: Value,
}
pub struct KnowledgePlugin;
impl Default for KnowledgePlugin {
    fn default() -> Self {
        Self
    }
}
impl KnowledgePlugin {
    pub fn new() -> Self {
        Self
    }
    fn qdrant_endpoint() -> String {
        std::env::var("COGNITIVE_MCP_QDRANT_URL")
            .or_else(|_| std::env::var("QDRANT_URL"))
            .unwrap_or_else(|_| DEFAULT_QDRANT_ENDPOINT.to_string())
    }

    fn endpoint_tcp_addr(endpoint: &str) -> Option<String> {
        let stripped = endpoint
            .strip_prefix("http://")
            .or_else(|| endpoint.strip_prefix("https://"))
            .unwrap_or(endpoint);
        let host_port = stripped.split('/').next()?;
        if host_port.contains(':') {
            Some(host_port.to_string())
        } else {
            None
        }
    }

    fn qdrant_reachable(endpoint: &str) -> bool {
        let addr = match Self::endpoint_tcp_addr(endpoint) {
            Some(addr) => addr,
            None => return false,
        };
        let socket_addr = match addr.parse() {
            Ok(addr) => addr,
            Err(_) => return false,
        };
        TcpStream::connect_timeout(&socket_addr, Duration::from_millis(750)).is_ok()
    }

    pub(crate) fn current_state() -> KnowledgeState {
        let qdrant_endpoint = Self::qdrant_endpoint();
        KnowledgeState {
            status: "active".to_string(),
            stores: json!([{"name": "qdrant", "type": "vector", "status": "unknown", "endpoint": qdrant_endpoint, "collections": [], "dimensions": 1024}, {"name": "cozo", "type": "graph", "status": "active", "relations": 0, "stored_procedure_count": 0}, {"name": "sled", "type": "kv", "status": "active", "path": "/dev/shm/plugin_schema.dat"}]),
            embedding: json!({"pipeline": "default", "provider": "voyage", "model": "voyage-4", "queue_size": 0, "worker_status": "idle", "chunk_size": 512, "chunk_overlap": 50}),
            config: json!({"qdrant_endpoint": qdrant_endpoint, "cozo_db": "/var/lib/op-dbus/cognitive.db", "auto_capture": false, "suggest_on_query": true}),
        }
    }
}
#[async_trait]
impl StatePlugin for KnowledgePlugin {
    fn name(&self) -> &str {
        "knowledge"
    }
    fn version(&self) -> &str {
        "1.0.0"
    }
    fn schema(&self) -> Option<PluginSchema> {
        Some(knowledge_schema())
    }
    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: String::new(),
                desired_hash: String::new(),
            },
        })
    }
    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }
    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }
    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::current_state())?,
            backend_checkpoint: None,
        })
    }
    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }
    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

pub(crate) fn knowledge_schema() -> PluginSchema {
    let state =
        simd_json::serde::to_owned_value(super::knowledge_plugin::KnowledgePlugin::current_state())
            .unwrap_or_else(|_| json!({}));
    schema_from_state(
        "knowledge",
        "data",
        "1.0.0",
        "Knowledge stores — Qdrant, CozoDB, Sled, embedding pipeline",
        &state,
    )
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("knowledge", |_ctx| std::sync::Arc::new(KnowledgePlugin::new()))
}

//! Generic, model-agnostic large-language-model plugin.
//!
//! The single inference surface — provider, model id, endpoint, and generation
//! params. The model is a FIELD, not the plugin's identity: swap `gemma3` →
//! `llama3`/`mistral` by changing `model_id`. This is the ONLY plugin that knows
//! about Ollama; consumers (e.g. `gemma_brain`) talk to this surface and embed
//! no model of their own.
//!
//! The plugin reports the *live* observed state: it queries the
//! provider (`GET {endpoint}/api/tags` for Ollama) for the available models and
//! reachability. The schema is published to the SHM folder/manifest by
//! op-projection's enumerator; this plugin does not self-write `/dev/shm`.

use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::PluginSchema;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
use std::time::Duration;

/// Generation parameters for an inference request.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.large-language-model.params.schema@v1"))]
pub struct GenerationParams {
    /// Sampling temperature (higher = more random).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.temperature@v1"))]
    pub temperature: f32,
    /// Maximum number of tokens to generate.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.max-tokens@v1"))]
    pub max_tokens: u32,
    /// Context window size, in tokens.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.context-window@v1"))]
    pub context_window: u32,
}

/// Top-level state for the generic large-language-model surface.
#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.large-language-model.schema@v1"))]
pub struct LargeLanguageModelState {
    /// Inference provider / runtime — the only Ollama-aware field.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.provider@v1"))]
    pub provider: String,
    /// Active model identifier, e.g. "gemma3", "llama3", "mistral". Swappable.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.model-id@v1"))]
    pub model_id: String,
    /// Provider endpoint URL.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.endpoint@v1"))]
    pub endpoint: String,
    /// Reachability of the provider: "online" or "offline" (observed).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.large-language-model.status@v1"))]
    pub status: String,
    /// Models reported available by the provider (observed live).
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.large-language-model.available-models@v1"))]
    pub available_models: Vec<String>,
    /// Default generation parameters.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "mut.service.large-language-model.params@v1"))]
    pub params: GenerationParams,
}

pub struct LargeLanguageModelPlugin;

impl Default for LargeLanguageModelPlugin {
    fn default() -> Self {
        Self
    }
}

impl LargeLanguageModelPlugin {
    pub fn new() -> Self {
        Self
    }

    fn env_or(key: &str, fallback: &str) -> String {
        std::env::var(key).unwrap_or_else(|_| fallback.to_string())
    }

    fn env_u32(key: &str, fallback: u32) -> u32 {
        std::env::var(key)
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(fallback)
    }

    fn env_f32(key: &str, fallback: f32) -> f32 {
        std::env::var(key)
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(fallback)
    }

    /// Configuration portion of the state, sourced from the environment.
    /// `status`/`available_models` are observed and filled in by the live query.
    fn config_state() -> LargeLanguageModelState {
        LargeLanguageModelState {
            provider: Self::env_or("LLM_PROVIDER", "ollama"),
            model_id: Self::env_or("LLM_MODEL_ID", "gemma3"),
            endpoint: Self::env_or("LLM_ENDPOINT", "http://127.0.0.1:11434"),
            status: "offline".to_string(),
            available_models: Vec::new(),
            params: GenerationParams {
                temperature: Self::env_f32("LLM_TEMPERATURE", 0.7),
                max_tokens: Self::env_u32("LLM_MAX_TOKENS", 2048),
                context_window: Self::env_u32("LLM_CONTEXT_WINDOW", 8192),
            },
        }
    }

    /// Query the Ollama-compatible provider for its model list. Returns `None`
    /// if the provider is unreachable or the response can't be parsed.
    async fn fetch_available_models(endpoint: &str) -> Option<Vec<String>> {
        let url = format!("{}/api/tags", endpoint.trim_end_matches('/'));
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(2))
            .build()
            .ok()?;
        let body = client.get(&url).send().await.ok()?.text().await.ok()?;
        let parsed: serde_json::Value = serde_json::from_str(&body).ok()?;
        let models = parsed.get("models").and_then(serde_json::Value::as_array)?;
        Some(
            models
                .iter()
                .filter_map(|m| m.get("name").and_then(serde_json::Value::as_str))
                .map(String::from)
                .collect(),
        )
    }
}

#[async_trait]
impl StatePlugin for LargeLanguageModelPlugin {
    fn name(&self) -> &str {
        "large_language_model"
    }

    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        let mut schema = large_language_model_schema();
        super::common::oscal::ensure_category_metadata_fields(&mut schema);
        Some(schema)
    }

    async fn calculate_diff(&self, _current: &Value, _desired: &Value) -> Result<StateDiff> {
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions: vec![],
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: "schema-declared".to_string(),
                desired_hash: "schema-declared".to_string(),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec![],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: uuid::Uuid::new_v4().to_string(),
            plugin: self.name().to_string(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: simd_json::serde::to_owned_value(Self::config_state())?,
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: true,
            supports_verification: true,
            atomic_operations: false,
        }
    }
}

/// Canonical `large_language_model` schema derived from
/// [`LargeLanguageModelState`] via schemars.
pub(crate) fn large_language_model_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(LargeLanguageModelState))
        .expect("schemars schema serializes to JSON");
    super::schemars_adapter::plugin_schema_from_json(
        "large_language_model",
        "1.0.0",
        "Generic model-agnostic LLM inference surface (provider, model id, endpoint, generation params); the model is a swappable field",
        &root,
    )
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("large_language_model", |_ctx| std::sync::Arc::new(LargeLanguageModelPlugin::new()))
}

//! login1 plugin - read-only D-Bus snapshot for sessions/seats

use anyhow::Result;
use async_trait::async_trait;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::{FieldSchema, FieldType, PluginSchema};
use serde::{Deserialize, Serialize};
use simd_json::{json, OwnedValue as Value};
use zbus::zvariant::OwnedObjectPath;
use zbus::{Connection, Proxy};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Login1State {
    pub sessions: Vec<SessionInfo>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionInfo {
    pub id: String,
    pub uid: u32,
    pub user: String,
    pub seat: String,
    pub path: String,
}

pub struct Login1Plugin;

impl Login1Plugin {
    pub fn new() -> Self {
        Self
    }

    async fn connect_manager(&self) -> Result<Proxy<'static>> {
        let conn = Connection::system().await?;
        let p = Proxy::new(
            &conn,
            "org.freedesktop.login1",
            "/org/freedesktop/login1",
            "org.freedesktop.login1.Manager",
        )
        .await?;
        Ok(p)
    }
}

impl Default for Login1Plugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl StatePlugin for Login1Plugin {
    fn name(&self) -> &str {
        "login1"
    }
    fn version(&self) -> &str {
        "1.0.0"
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(
            PluginSchema::builder("login1")
                .version("1.0.0")
                .description("Runtime login sessions")
                .field(
                    "sessions",
                    FieldSchema {
                        field_type: FieldType::Any,
                        required: true,
                        description: "Active sessions".to_string(),
                        default: Some(json!([])),
                        example: None,
                        constraints: Vec::new(),
                        read_only: false,
                        read_only_when: None,
                    },
                )
                .build(),
        )
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        let actions = if current != desired {
            vec![StateAction::Modify {
                resource: "login1".into(),
                changes: desired.clone(),
            }]
        } else {
            vec![]
        };
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
            },
        })
    }

    async fn apply_state(&self, _diff: &StateDiff) -> Result<ApplyResult> {
        Ok(ApplyResult {
            success: true,
            changes_applied: vec!["read-only".into()],
            errors: vec![],
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: format!("login1-{}", chrono::Utc::now().timestamp()),
            plugin: self.name().into(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: json!({}),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: false,
            supports_verification: false,
            atomic_operations: false,
        }
    }
}

// Self-registration: the plugin registry discovers this via inventory
// (single source of the catalog; no central dispatch list).
inventory::submit! {
    crate::default_registry::PluginReg::new("login1", |_ctx| std::sync::Arc::new(Login1Plugin::new()))
}

//! LXC plugin - Native Proxmox API LXC container management.
//!
//! Design
//! - Discovers LXC containers via native Proxmox REST API
//! - Creates, starts, stops, and deletes containers via API (no `pct` CLI)
//! - Correlates with OVS ports (vi{VMID}) for network integration
//! - Supports BTRFS golden images for instant container provisioning

use anyhow::Result;
use async_trait::async_trait;
use op_state::plugtree::PlugTree;
use op_state::{
    ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateAction, StateDiff, StatePlugin,
};
use op_state_store::PluginSchema;
#[cfg(test)]
use op_state_store::{Constraint, FieldSchema, FieldType};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use simd_json::prelude::*;
use simd_json::{json, OwnedValue as Value};
use std::collections::HashMap;
use std::fs;
use std::os::unix::fs::PermissionsExt;

fn default_bridge() -> String {
    "ovs-br0".to_string()
}

fn default_false() -> Option<bool> {
    Some(false)
}

fn default_properties() -> Option<HashMap<String, Value>> {
    Some(HashMap::new())
}

/// Runtime state of the LXC plugin.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.lxc.schema@v1"))]
pub struct LxcState {
    /// List of LXC containers.
    #[schemars(
        description = "List of LXC containers",
        extend("x-oscal-subid" = "exp.service.lxc.containers.render@v1")
    )]
    pub containers: Vec<ContainerInfo>,
}

/// Information about a single LXC container.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.lxc.container-info.schema@v1"))]
pub struct ContainerInfo {
    /// Container VMID.
    #[schemars(
        description = "Container VMID",
        pattern(r"^\d+$"),
        example = &"100",
        extend("readOnly" = true),
        extend("x-oscal-subid" = "obs.hardware.lxc.container-id@v1")
    )]
    pub id: String,
    /// Veth interface name.
    #[serde(default)]
    #[schemars(
        description = "Veth interface name",
        example = &"vi100",
        extend("x-oscal-subid" = "obs.network.lxc.veth-interface@v1")
    )]
    pub veth: String,
    /// OVS bridge name.
    #[serde(default = "default_bridge")]
    #[schemars(
        description = "OVS bridge name",
        default = "default_bridge",
        example = &"ovs-br0",
        extend("x-oscal-subid" = "obs.network.lxc.bridge@v1")
    )]
    pub bridge: String,
    /// Whether container is running.
    #[serde(default = "default_false")]
    #[schemars(
        description = "Whether container is running",
        default = "default_false",
        extend("x-oscal-subid" = "obs.service.lxc.running-status@v1")
    )]
    pub running: Option<bool>,
    /// Container properties (hostname, memory, cores, etc.).
    #[serde(default = "default_properties")]
    #[schemars(
        description = "Container properties (hostname, memory, cores, etc.)",
        default = "default_properties",
        with = "serde_json::Value",
        extend("x-oscal-subid" = "exp.service.lxc.properties.render@v1")
    )]
    pub properties: Option<HashMap<String, Value>>,
}

pub struct LxcPlugin;

impl LxcPlugin {
    pub fn new() -> Self {
        Self
    }

    /// Apply state for a single container
    pub async fn apply_container_state(&self, container: &ContainerInfo) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        // Check if container exists
        let current_containers = self.discover_from_proxmox().await?;
        let exists = current_containers.iter().any(|c| c.id == container.id);

        if !exists {
            // Create container
            match Self::create_container(container).await {
                Ok(_) => {
                    changes_applied.push(format!("Created container {}", container.id));

                    // Start it
                    if let Err(e) = Self::start_container(&container.id).await {
                        errors.push(format!("Failed to start container {}: {}", container.id, e));
                    } else {
                        changes_applied.push(format!("Started container {}", container.id));
                    }
                }
                Err(e) => {
                    errors.push(format!(
                        "Failed to create container {}: {}",
                        container.id, e
                    ));
                }
            }
        } else {
            changes_applied.push(format!("Container {} already exists", container.id));
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    /// Check if container is running via Proxmox API
    #[allow(dead_code)]
    async fn is_running_api(ct_id: &str) -> Result<bool> {
        let vmid: u32 = ct_id
            .parse()
            .map_err(|_| anyhow::anyhow!("Invalid container ID: {}", ct_id))?;

        let client = op_network::ProxmoxClient::from_env()?;
        client.is_running(vmid).await
    }

    /// Fallback: Check if container is running via cgroup (for when API is unavailable)
    fn is_running_cgroup(ct_id: &str) -> Option<bool> {
        // Proxmox systemd service path: pve-container@{vmid}.service (cgroup v2)
        let path = format!(
            "/sys/fs/cgroup/system.slice/pve-container@{}.service",
            ct_id
        );
        Some(fs::metadata(path).is_ok())
    }

    /// Discover containers from Proxmox API
    async fn discover_from_proxmox(&self) -> Result<Vec<ContainerInfo>> {
        let client = match op_network::ProxmoxClient::from_env() {
            Ok(c) => c,
            Err(_) => return Ok(Vec::new()),
        };

        // Check API availability
        if client.check_available().await.is_err() {
            log::debug!("Proxmox API not available, falling back to OVS discovery");
            return self.discover_from_ovs().await;
        }

        let containers = match client.list_containers().await {
            Ok(c) => c,
            Err(e) => {
                log::warn!(
                    "Failed to list containers via API: {}, falling back to OVS",
                    e
                );
                return self.discover_from_ovs().await;
            }
        };

        let ovsdb = op_network::rovs_proxy::OvsdbDbusClient::new();
        let bridges = ovsdb.list_bridges().await.unwrap_or_default();

        let mut results = Vec::new();
        for ct in containers {
            let ct_id = ct.vmid.to_string();
            let veth = format!("vi{}", ct_id);

            // Find which bridge this container's veth is on
            let mut found_bridge = String::new();
            for br in &bridges {
                if let Ok(ports) = ovsdb.list_bridge_ports(br).await {
                    if ports.contains(&veth) {
                        found_bridge = br.clone();
                        break;
                    }
                }
            }

            // Check running status
            let running = ct.status == "running";

            results.push(ContainerInfo {
                id: ct_id,
                veth,
                bridge: found_bridge,
                running: Some(running),
                properties: Some({
                    let mut props = HashMap::new();
                    if let Some(name) = ct.name {
                        props.insert("hostname".to_string(), Value::String(name));
                    }
                    props.insert("status".to_string(), Value::String(ct.status));
                    if let Some(mem) = ct.mem {
                        props.insert("memory_used".to_string(), json!(mem));
                    }
                    if let Some(maxmem) = ct.maxmem {
                        props.insert("memory_max".to_string(), json!(maxmem));
                    }
                    if let Some(cpu) = ct.cpu {
                        props.insert("cpu_usage".to_string(), json!(cpu));
                    }
                    if let Some(uptime) = ct.uptime {
                        props.insert("uptime".to_string(), json!(uptime));
                    }
                    props
                }),
            });
        }

        Ok(results)
    }

    /// Fallback: Discover containers from OVS ports (when API is unavailable)
    async fn discover_from_ovs(&self) -> Result<Vec<ContainerInfo>> {
        let client = op_network::rovs_proxy::OvsdbDbusClient::new();
        // If OVSDB is not reachable, return empty list
        if client.list_dbs().await.is_err() {
            return Ok(Vec::new());
        }

        let mut results = Vec::new();
        let bridges = client.list_bridges().await.unwrap_or_default();
        for br in bridges {
            let ports = client.list_bridge_ports(&br).await.unwrap_or_default();
            for p in ports {
                if let Some(ct_id) = p.strip_prefix("vi") {
                    // ensure ID is numeric-like
                    if ct_id.chars().all(|c| c.is_ascii_digit()) {
                        let running = Self::is_running_cgroup(ct_id);
                        results.push(ContainerInfo {
                            id: ct_id.to_string(),
                            veth: p.clone(),
                            bridge: br.clone(),
                            running,
                            properties: None,
                        });
                    }
                }
            }
        }
        Ok(results)
    }
}

impl LxcPlugin {
    /// Recursively copy a directory tree using direct file operations (AGENTS.md §4: no subprocess bypasses)
    async fn copy_dir_all(src: &str, dst: &str) -> Result<()> {
        tokio::fs::create_dir_all(dst).await?;
        let mut entries = tokio::fs::read_dir(src).await?;
        while let Some(entry) = entries.next_entry().await? {
            let file_name = entry.file_name();
            let src_path = format!("{}/{}", src, file_name.to_string_lossy());
            let dst_path = format!("{}/{}", dst, file_name.to_string_lossy());
            let file_type = entry.file_type().await?;
            if file_type.is_dir() {
                Box::pin(Self::copy_dir_all(&src_path, &dst_path)).await?;
            } else if file_type.is_symlink() {
                let target = tokio::fs::read_link(&src_path).await?;
                tokio::fs::symlink(target, &dst_path).await.ok();
            } else {
                tokio::fs::copy(&src_path, &dst_path).await?;
            }
        }
        Ok(())
    }
}

impl Default for LxcPlugin {
    fn default() -> Self {
        Self::new()
    }
}

#[async_trait]
impl PlugTree for LxcPlugin {
    fn pluglet_type(&self) -> &str {
        "container"
    }

    fn pluglet_id_field(&self) -> &str {
        "id"
    }

    fn extract_pluglet_id(&self, resource: &Value) -> Result<String> {
        resource
            .get("id")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .ok_or_else(|| anyhow::anyhow!("Container missing 'id' field"))
    }

    async fn apply_pluglet(&self, _pluglet_id: &str, desired: &Value) -> Result<ApplyResult> {
        let container: ContainerInfo = simd_json::serde::from_owned_value(desired.clone())?;
        self.apply_container_state(&container).await
    }

    async fn query_pluglet(&self, pluglet_id: &str) -> Result<Option<Value>> {
        let containers = self.discover_from_proxmox().await?;

        for container in containers {
            if container.id == pluglet_id {
                return Ok(Some(simd_json::serde::to_owned_value(container)?));
            }
        }

        Ok(None)
    }

    async fn list_pluglet_ids(&self) -> Result<Vec<String>> {
        let containers = self.discover_from_proxmox().await?;
        Ok(containers.into_iter().map(|c| c.id).collect())
    }
}

impl LxcPlugin {
    /// Find container's veth interface name
    async fn find_container_veth(ct_id: &str) -> Result<String> {
        // Standard Proxmox veth naming: vi{VMID}
        let veth_name = format!("vi{}", ct_id);

        // Check if it exists via rtnetlink
        let veth_interfaces = op_network::rtnetlink::list_veth_interfaces().await?;
        if veth_interfaces.contains(&veth_name) {
            return Ok(veth_name);
        }

        // Try to find any veth for this container
        for veth in veth_interfaces {
            if veth.contains(ct_id) {
                return Ok(veth);
            }
        }

        Err(anyhow::anyhow!(
            "Could not find veth interface for container {}",
            ct_id
        ))
    }

    /// Determine bridge based on network type
    fn get_bridge_for_network_type(container: &ContainerInfo) -> String {
        let network_type = container
            .properties
            .as_ref()
            .and_then(|p| p.get("network_type"))
            .and_then(|v| v.as_str())
            .unwrap_or("bridge");

        match network_type {
            "netmaker" => "mesh".to_string(),     // Netmaker mesh bridge
            "bridge" => container.bridge.clone(), // Traditional bridge (ovsbr0)
            _ => container.bridge.clone(),
        }
    }

    /// Create LXC container via native Proxmox API
    async fn create_container(container: &ContainerInfo) -> Result<()> {
        log::info!("Creating LXC container {} via Proxmox API", container.id);

        let vmid: u32 = container
            .id
            .parse()
            .map_err(|_| anyhow::anyhow!("Invalid container ID: {}", container.id))?;

        // Select bridge based on network type
        let bridge = Self::get_bridge_for_network_type(container);
        log::info!("Container {} will use bridge {}", container.id, bridge);

        // Extract properties with sensible defaults
        let props = container.properties.as_ref();

        // Check if using BTRFS golden image (fast path) or tar.zst template (slow path)
        let golden_image = props
            .and_then(|p| p.get("golden_image"))
            .and_then(|v| v.as_str());

        if let Some(golden_image_name) = golden_image {
            // BTRFS snapshot path - instant container creation
            return Self::create_container_from_btrfs_snapshot(
                container,
                golden_image_name,
                &bridge,
            )
            .await;
        }

        // Use native Proxmox API for template-based creation
        let template = props
            .and_then(|p| p.get("template"))
            .and_then(|v| v.as_str())
            .unwrap_or("local-btrfs:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst");

        let hostname = props
            .and_then(|p| p.get("hostname"))
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .unwrap_or_else(|| format!("ct{}", container.id));

        let memory = props
            .and_then(|p| p.get("memory"))
            .and_then(|v| v.as_u64())
            .unwrap_or(512) as u32;

        let swap = props
            .and_then(|p| p.get("swap"))
            .and_then(|v| v.as_u64())
            .unwrap_or(512) as u32;

        let storage = props
            .and_then(|p| p.get("storage"))
            .and_then(|v| v.as_str())
            .unwrap_or("local-btrfs");

        let rootfs_size = props
            .and_then(|p| p.get("rootfs_size"))
            .and_then(|v| v.as_u64())
            .unwrap_or(8);

        let rootfs = format!("{}:{}", storage, rootfs_size);

        let cores = props
            .and_then(|p| p.get("cores"))
            .and_then(|v| v.as_u64())
            .unwrap_or(2) as u32;

        let unprivileged = props
            .and_then(|p| p.get("unprivileged"))
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        let features = props
            .and_then(|p| p.get("features"))
            .and_then(|v| v.as_str())
            .unwrap_or("nesting=1");

        let firewall = props
            .and_then(|p| p.get("firewall"))
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        let net0 = format!(
            "name=eth0,bridge={},firewall={}",
            bridge,
            if firewall { "1" } else { "0" }
        );

        log::info!(
            "Creating container {}: template={}, memory={}MB, cores={}, rootfs={}",
            container.id,
            template,
            memory,
            cores,
            rootfs
        );

        // Build the request
        let config = op_network::CreateContainerRequest {
            vmid,
            ostemplate: template.to_string(),
            hostname: Some(hostname),
            memory: Some(memory),
            swap: Some(swap),
            cores: Some(cores),
            rootfs: Some(rootfs),
            net0: Some(net0),
            unprivileged: Some(unprivileged),
            features: Some(features.to_string()),
            onboot: props
                .and_then(|p| p.get("onboot"))
                .and_then(|v| v.as_bool()),
            protection: props
                .and_then(|p| p.get("protection"))
                .and_then(|v| v.as_bool()),
            nameserver: props
                .and_then(|p| p.get("nameserver"))
                .and_then(|v| v.as_str())
                .map(String::from),
            searchdomain: props
                .and_then(|p| p.get("searchdomain"))
                .and_then(|v| v.as_str())
                .map(String::from),
            storage: Some(storage.to_string()),
            ..Default::default()
        };

        // Execute via native API
        let client = op_network::ProxmoxClient::from_env()?;
        client.create_container_sync(&config, 300).await?;

        log::info!(
            "Container {} created successfully on bridge {} (via native API)",
            container.id,
            bridge
        );

        // Inject netmaker token for first-boot join (if netmaker network type)
        let network_type = props
            .and_then(|p| p.get("network_type"))
            .and_then(|v| v.as_str())
            .unwrap_or("bridge");

        if network_type == "netmaker" {
            Self::inject_netmaker_token(container, storage).await?;
        }

        Ok(())
    }

    /// Create LXC container from BTRFS golden image snapshot (instant provisioning)
    async fn create_container_from_btrfs_snapshot(
        container: &ContainerInfo,
        golden_image_name: &str,
        bridge: &str,
    ) -> Result<()> {
        log::info!(
            "Creating container {} from BTRFS golden image: {}",
            container.id,
            golden_image_name
        );

        let props = container.properties.as_ref();

        // Storage backend (configurable per container)
        let storage = props
            .and_then(|p| p.get("storage"))
            .and_then(|v| v.as_str())
            .unwrap_or("local-btrfs");

        // Proxmox storage paths (adjust based on storage.cfg configuration)
        let storage_path = format!("/var/lib/pve/{}", storage);
        let golden_image_path = format!("{}/templates/subvol/{}", storage_path, golden_image_name);
        let container_rootfs = format!("{}/images/{}/rootfs", storage_path, container.id);
        let container_dir = format!("{}/images/{}", storage_path, container.id);

        // Verify golden image exists
        if tokio::fs::metadata(&golden_image_path).await.is_err() {
            return Err(anyhow::anyhow!(
                "Golden image not found: {}. Create it with: sudo ./create-btrfs-golden-image.sh {}",
                golden_image_path,
                golden_image_name
            ));
        }

        // Check if golden image path exists (verified via direct file ops)
        if tokio::fs::metadata(&golden_image_path).await.is_err() {
            return Err(anyhow::anyhow!(
                "Golden image not found: {}",
                golden_image_path
            ));
        }

        // Check if path is on a btrfs filesystem via mountinfo
        let mounts = tokio::fs::read_to_string("/proc/self/mountinfo")
            .await
            .unwrap_or_default();
        let is_btrfs = mounts.lines().any(|line| {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() > 8 {
                parts[8] == "btrfs" && golden_image_path.starts_with(parts.get(4).unwrap_or(&""))
            } else {
                false
            }
        });

        if is_btrfs {
            log::info!("Golden image is on BTRFS: {}", golden_image_path);
        }

        log::info!("✓ Golden image verified: {}", golden_image_path);

        // Create container directory
        tokio::fs::create_dir_all(&container_dir).await?;

        // Create container rootfs via direct file operations (BTRFS snapshot via CLI is disabled per AGENTS.md §4)
        log::info!("Creating container rootfs directory...");
        tokio::fs::create_dir_all(&container_rootfs).await?;
        Self::copy_dir_all(&golden_image_path, &container_rootfs).await?;

        log::info!("✓ Container rootfs created: {}", container_rootfs);

        // Extract properties
        let hostname = props
            .and_then(|p| p.get("hostname"))
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
            .unwrap_or_else(|| format!("ct{}", container.id));

        let memory = props
            .and_then(|p| p.get("memory"))
            .and_then(|v| v.as_u64())
            .unwrap_or(512);

        let swap = props
            .and_then(|p| p.get("swap"))
            .and_then(|v| v.as_u64())
            .unwrap_or(512);

        let cores = props
            .and_then(|p| p.get("cores"))
            .and_then(|v| v.as_u64())
            .unwrap_or(2);

        let unprivileged = props
            .and_then(|p| p.get("unprivileged"))
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        let features = props
            .and_then(|p| p.get("features"))
            .and_then(|v| v.as_str())
            .unwrap_or("nesting=1");

        let firewall = props
            .and_then(|p| p.get("firewall"))
            .and_then(|v| v.as_bool())
            .unwrap_or(true);

        // Create Proxmox container configuration
        let config_path = format!("/etc/pve/lxc/{}.conf", container.id);
        let config_content = format!(
            r#"arch: amd64
cores: {}
hostname: {}
memory: {}
swap: {}
net0: name=eth0,bridge={},firewall={}
ostype: debian
rootfs: local-btrfs:images/{}/rootfs
unprivileged: {}
features: {}
"#,
            cores,
            hostname,
            memory,
            swap,
            bridge,
            if firewall { "1" } else { "0" },
            container.id,
            if unprivileged { "1" } else { "0" },
            features
        );

        // Add optional properties
        let mut config = config_content;

        if let Some(onboot) = props
            .and_then(|p| p.get("onboot"))
            .and_then(|v| v.as_bool())
        {
            config.push_str(&format!("onboot: {}\n", if onboot { "1" } else { "0" }));
        }

        if let Some(protection) = props
            .and_then(|p| p.get("protection"))
            .and_then(|v| v.as_bool())
        {
            config.push_str(&format!(
                "protection: {}\n",
                if protection { "1" } else { "0" }
            ));
        }

        if let Some(nameserver) = props
            .and_then(|p| p.get("nameserver"))
            .and_then(|v| v.as_str())
        {
            config.push_str(&format!("nameserver: {}\n", nameserver));
        }

        if let Some(searchdomain) = props
            .and_then(|p| p.get("searchdomain"))
            .and_then(|v| v.as_str())
        {
            config.push_str(&format!("searchdomain: {}\n", searchdomain));
        }

        // Write Proxmox config
        tokio::fs::write(&config_path, config).await?;

        log::info!("✓ Proxmox configuration written: {}", config_path);

        // Inject firstboot script if specified
        if let Some(firstboot_script) = props
            .and_then(|p| p.get("firstboot_script"))
            .and_then(|v| v.as_str())
        {
            Self::inject_firstboot_script(container, storage, firstboot_script).await?;
        }

        // Inject Netmaker token for netmaker network type
        let network_type = props
            .and_then(|p| p.get("network_type"))
            .and_then(|v| v.as_str())
            .unwrap_or("bridge");

        if network_type == "netmaker" {
            Self::inject_netmaker_token(container, storage).await?;
        }

        log::info!(
            "✓ Container {} created from golden image '{}' (BTRFS snapshot)",
            container.id,
            golden_image_name
        );

        Ok(())
    }

    /// Inject firstboot script into container rootfs
    async fn inject_firstboot_script(
        container: &ContainerInfo,
        storage: &str,
        script_content: &str,
    ) -> Result<()> {
        let rootfs = format!("/var/lib/pve/{}/images/{}/rootfs", storage, container.id);
        let script_path = format!("{}/usr/local/bin/lxc-firstboot.sh", rootfs);
        let service_path = format!("{}/etc/systemd/system/lxc-firstboot.service", rootfs);

        // Create script directory if needed
        tokio::fs::create_dir_all(format!("{}/usr/local/bin", rootfs)).await?;

        // Write firstboot script
        tokio::fs::write(&script_path, script_content).await?;

        // Make executable
        let perms = std::fs::Permissions::from_mode(0o755);
        tokio::fs::set_permissions(&script_path, perms).await?;

        // Create systemd service
        let service_content = r#"[Unit]
Description=LXC First Boot Initialization
After=network-online.target
Wants=network-online.target
ConditionPathExists=!/var/lib/lxc-firstboot-complete

[Service]
Type=oneshot
ExecStart=/usr/local/bin/lxc-firstboot.sh
RemainAfterExit=yes

[Install]
WantedBy=multi-user.target
"#
        .to_string();

        tokio::fs::create_dir_all(format!("{}/etc/systemd/system", rootfs)).await?;
        tokio::fs::write(&service_path, service_content).await?;

        // Enable service (create symlink)
        let symlink_dir = format!("{}/etc/systemd/system/multi-user.target.wants", rootfs);
        tokio::fs::create_dir_all(&symlink_dir).await?;

        let symlink_path = format!("{}/lxc-firstboot.service", symlink_dir);
        tokio::fs::symlink("../lxc-firstboot.service", &symlink_path)
            .await
            .ok(); // Ignore if exists

        log::info!(
            "✓ Firstboot script injected into container {}",
            container.id
        );

        Ok(())
    }

    /// Inject Netmaker enrollment token into container
    async fn inject_netmaker_token(container: &ContainerInfo, storage: &str) -> Result<()> {
        // Read token from host
        if let Ok(token_content) = tokio::fs::read_to_string("/etc/op-dbus/netmaker.env").await {
            for line in token_content.lines() {
                if let Some(token_value) = line.strip_prefix("NETMAKER_TOKEN=") {
                    let token_clean = token_value.trim_matches('"').trim();

                    let rootfs = format!("/var/lib/pve/{}/images/{}/rootfs", storage, container.id);
                    let token_path = format!("{}/etc/netmaker/enrollment-token", rootfs);

                    // Create netmaker directory
                    tokio::fs::create_dir_all(format!("{}/etc/netmaker", rootfs)).await?;

                    // Write token
                    tokio::fs::write(&token_path, token_clean).await?;

                    // Set permissions
                    let perms = std::fs::Permissions::from_mode(0o600);
                    tokio::fs::set_permissions(&token_path, perms).await?;

                    log::info!("✓ Netmaker token injected into container {}", container.id);
                    break;
                }
            }
        }

        Ok(())
    }

    /// Cleanup OVS port for deleted container
    async fn cleanup_ovs_port_for_container(ct_id: &str) -> Result<String> {
        let client = op_network::rovs_proxy::OvsdbDbusClient::new();

        // Find port names matching this container (vi{VMID} or internal_{VMID})
        let potential_ports = vec![
            format!("vi{}", ct_id),        // Proxmox veth pattern
            format!("internal_{}", ct_id), // Socket networking pattern
            format!("veth{}pl", ct_id),    // Alternative veth pattern
        ];

        // Try each potential port name
        for port_name in &potential_ports {
            // Check all bridges for this port
            if let Ok(bridges) = client.list_bridges().await {
                for bridge in bridges {
                    if let Ok(ports) = client.list_bridge_ports(&bridge).await {
                        if ports.contains(port_name) {
                            log::info!("Found port {} on bridge {}, removing", port_name, bridge);

                            // Delete the port using OVSDB
                            let operations = simd_json::json!([{
                                "op": "select",
                                "table": "Port",
                                "where": [["name", "==", port_name]],
                                "columns": ["_uuid"]
                            }]);

                            if let Ok(result) = client.transact_simd(operations).await {
                                if let Some(rows) = result[0]["rows"].as_array() {
                                    if let Some(first_row) = rows.first() {
                                        if let Some(uuid_array) = first_row["_uuid"].as_array() {
                                            if uuid_array.len() == 2 && uuid_array[0] == "uuid" {
                                                let port_uuid = uuid_array
                                                    .get(1)
                                                    .and_then(|v| v.as_str())
                                                    .ok_or_else(|| {
                                                        anyhow::anyhow!("invalid UUID array")
                                                    })?;

                                                // Get bridge UUID
                                                let bridge_ops = simd_json::json!([{
                                                    "op": "select",
                                                    "table": "Bridge",
                                                    "where": [["name", "==", &bridge]],
                                                    "columns": ["_uuid"]
                                                }]);

                                                if let Ok(bridge_result) =
                                                    client.transact_simd(bridge_ops).await
                                                {
                                                    if let Some(bridge_rows) =
                                                        bridge_result[0]["rows"].as_array()
                                                    {
                                                        if let Some(bridge_row) =
                                                            bridge_rows.first()
                                                        {
                                                            if let Some(bridge_uuid_array) =
                                                                bridge_row["_uuid"].as_array()
                                                            {
                                                                if bridge_uuid_array.len() == 2
                                                                    && bridge_uuid_array[0]
                                                                        == "uuid"
                                                                {
                                                                    let bridge_uuid =
                                                                        bridge_uuid_array.get(1).and_then(|v| v.as_str()).ok_or_else(|| anyhow::anyhow!("invalid bridge UUID array"))?;

                                                                    // Remove port from bridge and delete it
                                                                    let delete_ops = simd_json::json!([
                                                                        {
                                                                            "op": "mutate",
                                                                            "table": "Bridge",
                                                                            "where": [["_uuid", "==", ["uuid", bridge_uuid]]],
                                                                            "mutations": [
                                                                                ["ports", "delete", ["uuid", port_uuid]]
                                                                            ]
                                                                        },
                                                                        {
                                                                            "op": "delete",
                                                                            "table": "Port",
                                                                            "where": [["_uuid", "==", ["uuid", port_uuid]]]
                                                                        }
                                                                    ]);

                                                                    client
                                                                        .transact_simd(delete_ops)
                                                                        .await?;
                                                                    return Ok(port_name.clone());
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        Err(anyhow::anyhow!("No OVS port found for container {}", ct_id))
    }

    /// Start LXC container via native Proxmox API
    async fn start_container(ct_id: &str) -> Result<()> {
        log::info!("Starting container {} via Proxmox API", ct_id);

        let vmid: u32 = ct_id
            .parse()
            .map_err(|_| anyhow::anyhow!("Invalid container ID: {}", ct_id))?;

        let client = op_network::ProxmoxClient::from_env()?;
        client.start_container_sync(vmid, 60).await?;

        log::info!("Container {} started successfully (via native API)", ct_id);
        Ok(())
    }

    /// Stop LXC container via native Proxmox API
    #[allow(dead_code)]
    async fn stop_container(ct_id: &str) -> Result<()> {
        log::info!("Stopping container {} via Proxmox API", ct_id);

        let vmid: u32 = ct_id
            .parse()
            .map_err(|_| anyhow::anyhow!("Invalid container ID: {}", ct_id))?;

        let client = op_network::ProxmoxClient::from_env()?;
        client.stop_container_sync(vmid, 60).await?;

        log::info!("Container {} stopped successfully (via native API)", ct_id);
        Ok(())
    }

    /// Delete LXC container via native Proxmox API
    async fn delete_container(ct_id: &str, force: bool) -> Result<()> {
        log::info!(
            "Deleting container {} via Proxmox API (force={})",
            ct_id,
            force
        );

        let vmid: u32 = ct_id
            .parse()
            .map_err(|_| anyhow::anyhow!("Invalid container ID: {}", ct_id))?;

        let client = op_network::ProxmoxClient::from_env()?;

        // Stop if running
        if client.is_running(vmid).await.unwrap_or(false) {
            if force {
                client.stop_container_sync(vmid, 30).await?;
            } else {
                return Err(anyhow::anyhow!(
                    "Container {} is running. Stop it first or use force=true",
                    ct_id
                ));
            }
        }

        if force {
            let upid = client.force_delete_container(vmid).await?;
            client.wait_for_task(&upid, 120).await?;
        } else {
            client.delete_container_sync(vmid, 120).await?;
        }

        log::info!("Container {} deleted successfully (via native API)", ct_id);
        Ok(())
    }
}

#[async_trait]
impl StatePlugin for LxcPlugin {
    fn name(&self) -> &str {
        "lxc"
    }
    fn version(&self) -> &str {
        "2.0.0" // Version bump for native API support
    }

    fn schema(&self) -> Option<PluginSchema> {
        Some(lxc_schema())
    }

    fn is_available(&self) -> bool {
        // Try to check Proxmox API availability synchronously via environment
        // The actual check happens async in discovery
        std::path::Path::new("/etc/pve").exists()
    }

    fn unavailable_reason(&self) -> String {
        "Proxmox VE not detected (/etc/pve not found) - this plugin requires Proxmox VE".to_string()
    }

    async fn calculate_diff(&self, current: &Value, desired: &Value) -> Result<StateDiff> {
        // For now, emit a single modify if different; once lifecycle is defined, compute granular actions.
        let actions = if current != desired {
            vec![StateAction::Modify {
                resource: "lxc".into(),
                changes: desired.clone(),
            }]
        } else {
            vec![]
        };
        Ok(StateDiff {
            plugin: self.name().to_string(),
            actions,
            metadata: DiffMetadata {
                timestamp: chrono::Utc::now().timestamp(),
                current_hash: format!("{:x}", md5::compute(simd_json::to_string(current)?)),
                desired_hash: format!("{:x}", md5::compute(simd_json::to_string(desired)?)),
            },
        })
    }

    async fn apply_state(&self, diff: &StateDiff) -> Result<ApplyResult> {
        let mut changes_applied = Vec::new();
        let mut errors = Vec::new();

        for action in &diff.actions {
            match action {
                StateAction::Create {
                    resource: _,
                    config,
                } => {
                    let container: ContainerInfo =
                        simd_json::serde::from_owned_value(config.clone())?;

                    // 1. Create LXC container via native API
                    match Self::create_container(&container).await {
                        Ok(_) => {
                            changes_applied.push(format!(
                                "Created container {} (via native Proxmox API)",
                                container.id
                            ));

                            // 2. Start container to create veth interface
                            if let Err(e) = Self::start_container(&container.id).await {
                                errors.push(format!(
                                    "Failed to start container {}: {}",
                                    container.id, e
                                ));
                                continue;
                            }

                            // Wait for veth to appear
                            tokio::time::sleep(tokio::time::Duration::from_secs(2)).await;

                            // 3. Find and rename veth
                            let veth_name = format!("vi{}", container.id);
                            match Self::find_container_veth(&container.id).await {
                                Ok(old_veth) => {
                                    log::info!(
                                        "Found veth {} for container {}",
                                        old_veth,
                                        container.id
                                    );

                                    if old_veth != veth_name {
                                        match op_network::rtnetlink::link_set_name(
                                            &old_veth, &veth_name,
                                        )
                                        .await
                                        {
                                            Ok(_) => {
                                                changes_applied.push(format!(
                                                    "Renamed {} to {}",
                                                    old_veth, veth_name
                                                ));
                                            }
                                            Err(e) => {
                                                log::warn!("Failed to rename veth: {}", e);
                                                // Continue anyway, veth might work with original name
                                            }
                                        }
                                    }

                                    // 4. Network enrollment based on type
                                    let network_type = container
                                        .properties
                                        .as_ref()
                                        .and_then(|p| p.get("network_type"))
                                        .and_then(|v| v.as_str())
                                        .unwrap_or("bridge");

                                    let target_bridge = match network_type {
                                        "netmaker" => "mesh".to_string(),
                                        _ => container.bridge.clone(),
                                    };

                                    if !target_bridge.is_empty() {
                                        let ovsdb_client =
                                            op_network::rovs_proxy::OvsdbDbusClient::new();
                                        match ovsdb_client
                                            .add_port(&target_bridge, &veth_name)
                                            .await
                                        {
                                            Ok(_) => {
                                                changes_applied.push(format!(
                                                    "Added {} to bridge {}",
                                                    veth_name, target_bridge
                                                ));
                                            }
                                            Err(e) => {
                                                errors.push(format!(
                                                    "Failed to add port to bridge: {}",
                                                    e
                                                ));
                                            }
                                        }
                                    }
                                }
                                Err(e) => {
                                    log::warn!(
                                        "Failed to find veth for container {}: {}",
                                        container.id,
                                        e
                                    );
                                    // Continue - container was created, just couldn't configure OVS
                                }
                            }
                        }
                        Err(e) => {
                            errors.push(format!(
                                "Failed to create container {}: {}",
                                container.id, e
                            ));
                        }
                    }
                }
                StateAction::Modify {
                    resource,
                    changes: _,
                } => {
                    // Handle container state changes (start/stop)
                    log::info!(
                        "Modify operation for container {} (not yet implemented)",
                        resource
                    );
                    changes_applied.push(format!("Skipped modify for {}", resource));
                }
                StateAction::Delete { resource } => {
                    // Delete container and cleanup OVS ports
                    log::info!("Deleting container {} and cleaning up OVS ports", resource);

                    // First, try to find and cleanup the OVS port for this container
                    let cleanup_result = Self::cleanup_ovs_port_for_container(resource).await;
                    match cleanup_result {
                        Ok(port_name) => {
                            log::info!(
                                "Cleaned up OVS port {} for container {}",
                                port_name,
                                resource
                            );
                            changes_applied.push(format!(
                                "Removed OVS port {} for container {}",
                                port_name, resource
                            ));
                        }
                        Err(e) => {
                            log::warn!(
                                "Could not cleanup OVS port for container {}: {}",
                                resource,
                                e
                            );
                        }
                    }

                    // Then delete the container via native API
                    match Self::delete_container(resource, true).await {
                        Ok(_) => {
                            changes_applied.push(format!(
                                "Deleted container {} (via native Proxmox API)",
                                resource
                            ));
                        }
                        Err(e) => {
                            errors.push(format!("Failed to delete container {}: {}", resource, e));
                        }
                    }
                }
                StateAction::NoOp { .. } => {}
            }
        }

        Ok(ApplyResult {
            success: errors.is_empty(),
            changes_applied,
            errors,
            checkpoint: None,
        })
    }

    async fn verify_state(&self, _desired: &Value) -> Result<bool> {
        Ok(true)
    }

    async fn create_checkpoint(&self) -> Result<Checkpoint> {
        Ok(Checkpoint {
            id: format!("lxc-{}", chrono::Utc::now().timestamp()),
            plugin: self.name().into(),
            timestamp: chrono::Utc::now().timestamp(),
            state_snapshot: json!({}),
            backend_checkpoint: None,
        })
    }

    async fn rollback(&self, _checkpoint: &Checkpoint) -> Result<()> {
        Ok(())
    }

    fn capabilities(&self) -> PluginCapabilities {
        PluginCapabilities {
            supports_rollback: false,
            supports_checkpoints: false,
            supports_verification: false,
            atomic_operations: false,
        }
    }
}

/// LXC schema derived from the typed [`LxcState`] struct via schemars.
pub(crate) fn lxc_schema() -> PluginSchema {
    let root = serde_json::to_value(schemars::schema_for!(LxcState))
        .expect("schemars schema serializes to JSON");
    let mut schema = super::schemars_adapter::plugin_schema_from_json(
        "lxc",
        "2.0.0",
        "LXC container management via native Proxmox API",
        &root,
    );
    // create_container uses ContainerInfo directly as input
    schema.methods.insert("create_container".to_string(), super::plugin_schema_defs::method_decl_from_schemars::<ContainerInfo>(
        "create_container",
        op_state_store::SideEffect::Mutation,
        false,
        "cap.service.lxc.container.create@v1",
        "mut.service.lxc.container.create@v1",
    ));
    // delete_container needs a simple input struct
    schema.methods.insert("delete_container".to_string(), super::plugin_schema_defs::method_decl_from_schemars::<DeleteContainerInput>(
        "delete_container",
        op_state_store::SideEffect::Mutation,
        false,
        "cap.service.lxc.container.delete@v1",
        "mut.service.lxc.container.delete@v1",
    ));
    // attach_container_port - passes through to rovs_commands for OVS port attachment
    schema.methods.insert("attach_container_port".to_string(), super::plugin_schema_defs::method_decl_from_schemars::<ContainerInfo>(
        "attach_container_port",
        op_state_store::SideEffect::Mutation,
        false,
        "cap.network.lxc.port.attach@v1",
        "mut.network.lxc.port.attach@v1",
    ));
    schema
}

